import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.v1TqQkD7.js";const o="/ESI.ts/assets/vsm-era1-local.BJJ8sy7b.svg",s="/ESI.ts/assets/vsm-era2-rampup.kZZTKu28.svg",i="/ESI.ts/assets/vsm-current-state.CyjR3jfa.svg",d="/ESI.ts/assets/vsm-future-state.Cz5YooMy.svg",b=JSON.parse('{"title":"Lean by Decision: the ESI.ts Decision Record, v7 to 11.0","description":"","frontmatter":{"title":"Lean by Decision: the ESI.ts Decision Record, v7 to 11.0","sourceFile":"guides/LEAN-DECISIONS.md"},"headers":[],"relativePath":"guide/lean-decisions.md","filePath":"guide/lean-decisions.md"}'),h={name:"guide/lean-decisions.md"};function l(c,e,m,p,u,g){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="lean-by-decision-the-esits-decision-record-v7-to-110" tabindex="-1">Lean by Decision: the ESI.ts Decision Record, v7 to 11.0 <a class="header-anchor" href="#lean-by-decision-the-esits-decision-record-v7-to-110" aria-label="Permalink to &quot;Lean by Decision: the ESI.ts Decision Record, v7 to 11.0&quot;">​</a></h1><p><strong>Leigh Griffin</strong> · 27 September 2026 · a standalone record of how I built ESI.ts, and why</p><hr><h2 id="why-this-document-exists" tabindex="-1">Why this document exists <a class="header-anchor" href="#why-this-document-exists" aria-label="Permalink to &quot;Why this document exists&quot;">​</a></h2><p>I am writing a book on Lean software development for Manning. ESI.ts, my TypeScript client for EVE Online&#39;s ESI API, is where I test the ideas on myself. From v7 onwards I built most of it with Claude as the engineer and myself as the maintainer, the customer and, for a long time, the only person who could press merge.</p><p>This document has two readers. The first is me: a record of the decisions I made and the Lean reasoning behind each one, measured against what actually happened. The second is Claude. I want any Claude session that works with me to understand how I think, not just what I decided, so that when it meets a situation I have not covered it reasons the way I would. Where a decision carries a lesson I want an agent to apply, I say so directly under <strong>For Claude</strong>.</p><p>It is standalone. Everything it cites is in the ESI.ts repository (<code>github.com/lgriffin/ESI.ts</code>) or in the data files beside it, under <code>guides/lean/</code>. Every number comes from a timestamp that already existed: GitHub pull requests and Actions runs, git tags, the changelog, and the project threads where I worked with Claude from 26 September. Nothing was measured with a stopwatch, and where a number is an estimate I say so.</p><hr><h2 id="part-1--the-lens-i-apply" tabindex="-1">Part 1 · The lens I apply <a class="header-anchor" href="#part-1--the-lens-i-apply" aria-label="Permalink to &quot;Part 1 · The lens I apply&quot;">​</a></h2><p>I do not use Lean as a vocabulary. I use it as a small set of questions I ask of every change. In software terms they are:</p><ol><li><strong>What does the customer actually receive?</strong> For ESI.ts the customer is a developer building an EVE tool, and the thing they receive is whatever ESI sends, passed through my client. Value is defined there, at the wire, not in my types or my plans. My charter puts it as: <em>the OpenAPI spec is upstream.</em></li><li><strong>Where does the work wait?</strong> Almost all lead time is waiting. Agents made building nearly free, which does not change that; it makes it the only thing left to improve.</li><li><strong>Does the line stop itself?</strong> Quality is built in by machines that stop the line at the first abnormality (jidoka), not inspected in afterwards by a person. A check that can be ignored is not a check.</li><li><strong>Is anyone pulling this?</strong> If nobody asked for it, it is overproduction, whether a person or a bot made it.</li><li><strong>Is the standard written down, and does it only move forward?</strong> Standard work is what lets the next person, or the next agent, start where the last one stopped. Ratchets let quality move up and never down.</li><li><strong>Who has the information?</strong> Decisions should sit with whoever has the information to make them. A person should decide only what a machine cannot.</li><li><strong>What did we learn, and is it in the system now?</strong> Kaizen that lives in someone&#39;s head is gone the next morning. It has to be a PR, a rule, or a memory.</li></ol><p>My engineering charter (<code>guides/CHARTER.md</code>) states the product side of this as seven positions, and I hold every change to them:</p><ul><li>The OpenAPI spec is upstream.</li><li>Hand-write where judgement matters.</li><li>Tolerate additive change.</li><li>Resilience is pluggable.</li><li>Secure by construction.</li><li>The specification executes.</li><li>Verifiable supply chain.</li></ul><hr><h2 id="part-2--the-value-stream" tabindex="-1">Part 2 · The value stream <a class="header-anchor" href="#part-2--the-value-stream" aria-label="Permalink to &quot;Part 2 · The value stream&quot;">​</a></h2><p>The unit of flow is <strong>one change</strong>: one pull request, carrying one concern. The stream runs from an ask (mine, or an issue, or a bot) to a commit on <code>master</code>, and on to a release that a consumer installs from npm.</p><p>The stream changed shape three times between v7 and 11.0, and each shape has its own value stream map below. The shapes matter more than any single number, because each one moved the constraint somewhere new.</p><table tabindex="0"><thead><tr><th>Era</th><th>When</th><th>How the work ran</th><th>PRs merged</th><th>PR open → merged (median)</th><th>p85</th></tr></thead><tbody><tr><td>0</td><td>Late June to 8 July</td><td>Me at the keyboard with Claude Code, merging my own PRs</td><td>25</td><td>7 min</td><td>22 min</td></tr><tr><td>1a</td><td>8 July to 5 August (v7)</td><td>Same</td><td>19</td><td>33 min</td><td>64 min</td></tr><tr><td>1b</td><td>5 August to 15 September (v8, v9)</td><td>Same</td><td>65</td><td>16 min</td><td>52 min</td></tr><tr><td>2</td><td>15 to 22 September (v10 ramp-up)</td><td>Many agents in parallel, me merging</td><td>66</td><td>37 min</td><td><strong>6 h 22 min</strong></td></tr><tr><td>3</td><td>26 September to 27 September 11:42</td><td>Cloud threads, me merging from my phone</td><td>24</td><td><strong>1 h 54 min</strong></td><td>3 h 37 min</td></tr><tr><td>4</td><td>From 27 September 11:42</td><td>Cloud threads merging their own PRs at green</td><td>9</td><td><strong>14 min</strong></td><td>45 min</td></tr></tbody></table><p><em>Human-authored PRs only. PR open to merged excludes the time spent building before the PR opened. Source: <code>lean/data/all-prs.csv</code>.</em></p><p>That table is the whole story in miniature. When I was the entire line, there was no queue at merge. When I multiplied the line with agents but kept the merge in my hands, a queue formed exactly there. When I handed the merge to the line, the queue disappeared and the parallelism stayed.</p><hr><h2 id="part-3--the-maps" tabindex="-1">Part 3 · The maps <a class="header-anchor" href="#part-3--the-maps" aria-label="Permalink to &quot;Part 3 · The maps&quot;">​</a></h2><h3 id="era-1--one-maintainer-at-the-keyboard-with-local-agents" tabindex="-1">Era 1 · One maintainer at the keyboard with local agents <a class="header-anchor" href="#era-1--one-maintainer-at-the-keyboard-with-local-agents" aria-label="Permalink to &quot;Era 1 · One maintainer at the keyboard with local agents&quot;">​</a></h3><p><img src="'+o+'" alt="Era 1 value stream map"></p><p>I worked in Claude Code on my own machine, opened each PR and merged it myself. Lead time from PR to <code>master</code> was minutes because I was present at every step. The waste in this era was not in the main line. It was in the side streams: Dependabot opened 73 PRs from June onwards and 45 of them (62%) were closed without merging; its PRs waited a median of 91 hours in July and 48 hours from August to mid-September before anyone touched them. And I released too often: four major versions in ten weeks (7.0.0 on 8 July, 8.0.0 on 5 August, 9.0.0 on 12 August, 10.0.0 on 17 September), with version sources that drifted so far that requests told CCP they came from <code>esi.ts/9.2.0</code> while <code>package.json</code> said 9.6.1.</p><h3 id="era-2--the-parallel-ramp-up" tabindex="-1">Era 2 · The parallel ramp-up <a class="header-anchor" href="#era-2--the-parallel-ramp-up" aria-label="Permalink to &quot;Era 2 · The parallel ramp-up&quot;">​</a></h3><p><img src="'+s+'" alt="Era 2 value stream map"></p><p>In mid-September I ran the &quot;Hermes-grade&quot; ramp-up: many agents working its phases in parallel against the charter. Weekly merged PRs went from 5 to 12 to 63; there were 262 commits on 16 and 17 September alone. The new test tiers found ten real defects in their first week without a single consumer bug report. But capacity rose and two steps did not: my merge (median 37 minutes, p85 over six hours) and release-please, which cut five releases (10.0.0, 10.1.0, 10.1.1, 10.2.0, 10.2.1) in three days. The burst itself was mura: 262 commits in two days, then a handful a day.</p><h3 id="era-3--cloud-threads-merging-by-hand" tabindex="-1">Era 3 · Cloud threads, merging by hand <a class="header-anchor" href="#era-3--cloud-threads-merging-by-hand" aria-label="Permalink to &quot;Era 3 · Cloud threads, merging by hand&quot;">​</a></h3><p><img src="'+i+'" alt="Era 3 value stream map"></p><p>On 26 September I moved the work into a Claude project: a coordinator that routes my asks and a thread per ask that builds, tests and drives a PR green. I measured this era from my ask, not from the PR opening, because the threads timestamp everything. The median change took <strong>8 minutes</strong> from my ask to an open, tested PR and <strong>121 minutes</strong> to reach <code>master</code>. About 21 minutes of that was work, so flow efficiency was about <strong>17%</strong>. Half of all lead time was green PRs waiting for me. Because I merged from my phone when I could, I merged in batches of two to six, and the batches caused a merge conflict (#417 and #419), a red <code>master</code> (#420 merged minutes before its own fix, repaired by #426), and a change merged into a branch that had already landed (#431, redone as #439).</p><h3 id="era-4--merge-at-green-and-the-future-state" tabindex="-1">Era 4 · Merge at green, and the future state <a class="header-anchor" href="#era-4--merge-at-green-and-the-future-state" aria-label="Permalink to &quot;Era 4 · Merge at green, and the future state&quot;">​</a></h3><p><img src="'+d+'" alt="Future-state value stream map"></p><p>At 11:42 on 27 September I wrote &quot;Please merge as needed&quot;. The gate did not change: the same 35 required checks, every review thread answered and resolved. Only the hand on the button changed. Ready-to-merged fell from a 42-minute median to zero. Clean changes went from my ask to <code>master</code> in 17 and 18 minutes (#441, #442), a flow efficiency of about 85%. The map shows the rest of the future state: tests running in the agent&#39;s own environment before CI (K1), agent load levelled across the usage window (K3), and the last manual step taken out of release (K4).</p><hr><h2 id="part-4--the-decisions" tabindex="-1">Part 4 · The decisions <a class="header-anchor" href="#part-4--the-decisions" aria-label="Permalink to &quot;Part 4 · The decisions&quot;">​</a></h2><p>Each decision has the same shape: what I decided, the Lean reasoning, and the evidence of what happened. PR numbers are on <code>github.com/lgriffin/ESI.ts</code>.</p><h3 id="foundations-i-inherited-into-v7" tabindex="-1">Foundations I inherited into v7 <a class="header-anchor" href="#foundations-i-inherited-into-v7" aria-label="Permalink to &quot;Foundations I inherited into v7&quot;">​</a></h3><p>Three decisions made just before v7 shaped everything after it.</p><p><strong>Types come from the spec, not from me</strong> (v5, #78, #81, June). Types, cache TTLs, rate-limit groups and scopes are generated from ESI&#39;s own OpenAPI document. <em>Lean reasoning:</em> the supplier&#39;s specification is the definition of the part; copying it by hand is a second source of truth that will drift. <em>Evidence:</em> it made every later drift check possible.</p><p><strong>Behaviour is written as requirements before code</strong> (#88, #92, June and July). The BDD suite moved to Gherkin and then to EARS patterns. <em>Lean reasoning:</em> standard work for requirements; a requirement you can execute is one you cannot quietly weaken.</p><p><strong>Validate every response at runtime, but tolerate additions</strong> (v6, #93, 3 July). Every response passes a Zod schema; schemas use loose objects so a new field from CCP never breaks a consumer. <em>Lean reasoning:</em> jidoka for data: stop on a real abnormality, not on harmless variation. A line that stops for everything gets its andon cord disconnected. <em>Evidence:</em> live validation immediately found schemas that did not match ESI (#94, #101), which is the whole point.</p><h3 id="era-1--v7-to-v99-july-to-mid-september" tabindex="-1">Era 1 · v7 to v9.9 (July to mid-September) <a class="header-anchor" href="#era-1--v7-to-v99-july-to-mid-september" aria-label="Permalink to &quot;Era 1 · v7 to v9.9 (July to mid-September)&quot;">​</a></h3><p><strong>1 · One spec, the newest one</strong> (v7.0.0, #102, 8 July). I moved from Swagger 2.0 to OpenAPI 3.1 and fetched one spec instead of two. <em>Lean reasoning:</em> two sources of the same truth is a waste and a defect generator. <em>Evidence:</em> 161 generated interfaces instead of 147, and one fetch instead of two. It was a major version, and that is a cost I return to in decision 26.</p><p><strong>2 · Inspect the supplier&#39;s material on arrival</strong> (v7.1.0, #103). Redocly lints ESI&#39;s own spec before I generate from it. <em>Lean reasoning:</em> incoming inspection. If CCP ships a broken spec, I want to know before it becomes my broken types.</p><p><strong>3 · Move detection upstream</strong> (v7.2 to v7.3, #104, #112, #113, July). Contract testing against the live spec, property-based fuzzing, and schema drift as a <em>blocking</em> check, plus compile-time spec-to-Zod alignment. <em>Lean reasoning:</em> find the defect at the station that makes it. <em>Evidence:</em> the fuzzing alone added 601 tests on the path-parameter and query validators, and years later it is the tier that proved the <code>..</code> path fix (#430).</p><p><strong>4 · Make the consumer&#39;s mistakes impossible</strong> (#115, #116, 14 July). Branded ID types and an <code>EsiResult&lt;T&gt;</code> safe mode. <em>Lean reasoning:</em> poka-yoke for the customer. A <code>characterId</code> cannot be passed where an <code>allianceId</code> belongs.</p><p><strong>5 · An andon that does not stop the line is not an andon</strong> (#117, 14 July). I removed <code>continue-on-error</code> from three CI jobs. <em>Lean reasoning:</em> a check that can fail without consequence teaches everyone to ignore it. <em>For Claude:</em> never make a failing check non-blocking to get green. If a check is wrong, fix the check in its own PR.</p><p><strong>6 · Put slow inspection where it is cheap, then ratchet it</strong> (#126 on 27 July, #168 on 14 August, then #344, #359, #371 in September). Mutation testing started non-blocking, moved to nightly, and came back to the PR path only when it could run on the files a PR changes, gated per directory against floors the nightlies had earned. <em>Lean reasoning:</em> inspection has a cost. Put the full inspection in a nightly loop that does not hold anyone&#39;s work, and put a right-sized version on the line. Ratchets make improvement one-way. <em>Evidence:</em> by 19 September every logger, util and pagination mutant was killed (#374, #375).</p><p><strong>7 · 5S the codebase before building on it</strong> (#136, 5 August). Dead code, duplicate schemas and docs drift removed as &quot;phase 0&quot;. <em>Lean reasoning:</em> sort, set in order, shine. You cannot see abnormality in a cluttered workplace.</p><p><strong>8 · Make resilience a port, not a product</strong> (#141, #143, 5 August). The request handler became a pipeline of modules with an injectable retry strategy. <em>Lean reasoning:</em> flexibility; a component that can be swapped without changing its neighbours is the software form of quick changeover.</p><p><strong>9 · Safe by default, and ship less surface</strong> (v9.0.0, #145, #154, 12 August). Retries default to three with backoff; generated schemas left the public API; sub-path exports (<code>/schemas</code>, <code>/errors</code>, <code>/testing</code>) let a consumer pull only what they use. <em>Lean reasoning:</em> the default is the standard; exported surface is inventory I must maintain forever.</p><p><strong>10 · Route the andon to the owner</strong> (#160, 14 August). The nightly spec-drift check files an issue instead of turning someone&#39;s PR red. <em>Lean reasoning:</em> stop the right line. A drift in ESI is not the fault of whoever happens to have a PR open. <em>For Claude:</em> when a failure is not caused by the change under test, route it to where it belongs rather than blocking the change.</p><p><strong>11 · Tolerate what ESI adds, pin what it removes</strong> (#156, #188, August). A configurable compatibility date and resilient enum validation. <em>Lean reasoning:</em> value is what the customer receives today, and ESI changes by date.</p><p><strong>12 · Secure the shipping dock</strong> (#176, #191, #192, #193, #199, 18 to 24 August). OSSF Scorecard, ETag cache isolated per token (a real cross-tenant leak, #191), workflows hardened against script injection, actions pinned by SHA, npm provenance, cosign signatures and checksums. <em>Lean reasoning:</em> quality includes what the customer cannot see. A supply chain you cannot verify is a defect waiting for a trigger.</p><p><strong>13 · Make the work visible to agents</strong> (#196, 24 August). I adopted Beads as the issue tracker agents read and write. <em>Lean reasoning:</em> visual management. <em>Evidence and caveat:</em> it worked while I ran agents locally; by late September my local Beads copy had drifted from GitHub, which cost a thread time to rediscover what was really open. A second board is a second source of truth.</p><p><strong>14 · Fail only on what this change introduced</strong> (#234, #248, 9 September). Schemathesis moved to nightly; <code>npm audit</code> on the PR path became diff-aware, failing only on advisories the PR adds, with accepted risks in an allowlist that <em>must</em> carry an expiry date. <em>Lean reasoning:</em> don&#39;t stop one station for another station&#39;s defect; and a workaround without an expiry becomes permanent. <em>For Claude:</em> any exception you record needs a reason and a date it stops being acceptable.</p><p><strong>15 · One version, one source</strong> (#249, 9 September). Version sources realigned after the stale user agent. <em>Lean reasoning:</em> if a number exists in three places, two of them are wrong.</p><p><strong>16 · Requirements that execute, derived from what the tests assert</strong> (v9.8.0, #251, 10 September). All feature files rewritten as atomic EARS requirements, one per <code>Rule:</code>, with a CI-gated audit that rejects vague language. <em>Lean reasoning:</em> standard work for specification. <em>Evidence:</em> deriving each requirement from its assertions exposed scenarios whose titles claimed coverage their assertions never provided. False confidence is a hidden defect.</p><p><strong>17 · Write the charter</strong> (v9.9.0, #288, 15 September). Every requirement numbered, in EARS form, with the script or CI job that enforces it, a status of Enforced, Practised, Partial or Gap, and a gap register. <em>Lean reasoning:</em> the charter is my standard work, and the gap register is a visible problem board. A requirement without a mechanism says so rather than pretending.</p><h3 id="era-2--the-v10-ramp-up-15-to-22-september" tabindex="-1">Era 2 · The v10 ramp-up (15 to 22 September) <a class="header-anchor" href="#era-2--the-v10-ramp-up-15-to-22-september" aria-label="Permalink to &quot;Era 2 · The v10 ramp-up (15 to 22 September)&quot;">​</a></h3><p><strong>18 · Ramp up in parallel, against the charter</strong> (#302, #309, #310, 16 September). Agents worked the ramp-up phases at the same time. <em>Lean reasoning:</em> the standard was written, so the work could be distributed. <em>Evidence:</em> 63 PRs merged that week. <em>What I would change:</em> see decision 26 on mura.</p><p><strong>19 · Match the wire, even when it breaks</strong> (v10.0.0, #317, #327, 16 and 17 September). Response schemas and test builders aligned with what ESI actually sends. Fields widened, some tightened, corporation and wallet types split. <em>Lean reasoning:</em> a type that promises a field ESI never sends is a defect shipped to the customer.</p><p><strong>20 · Mistake-proofing designed for agents</strong> (#323, #324, #325, #326, 17 September). Lints that ratchet wall-clock and <code>Math.random</code> use in <code>src/</code>; lints that reject focused, skipped, assertion-free or silenced tests; a check that fails when a public export has no test referencing it; documentation examples type-checked against the packed package. <em>Lean reasoning:</em> agents write a lot of code quickly. The cheapest defect is the one a lint makes impossible. <em>For Claude:</em> treat these lints as the standard. Never add to a baseline; baselines only shrink.</p><p><strong>21 · Add tiers that find what the others cannot</strong> (#339, #340, #342, #343, #345, 17 September). A composition and concurrency tier with a deterministic interleaving scheduler, model-based properties with a vacuity check, a Node × TypeScript × resolution consumer matrix, a transport fault catalogue, statistical benchmarks and a heap soak. <em>Evidence:</em> five pipeline races and five further defects (circuit breaker, pagination cache, backoff) found in the first run, all fixed before any consumer saw them.</p><p><strong>22 · Let the workstation run the whole line</strong> (#352, 18 September). <code>check:local</code> runs every offline CI tier with one command. <em>Lean reasoning:</em> jidoka belongs at the station. CI should confirm, not discover.</p><p><strong>23 · The thing shipped is the thing tested</strong> (#364, #365, #372, #393, 18 to 21 September). Publish the tarball that was tested and signed; verify what npm actually serves; attach a signed CycloneDX SBOM; a post-publish canary checks the release assets. <em>Lean reasoning:</em> inspect at the customer&#39;s receiving dock, because that is where value is judged.</p><p><strong>24 · Give agents the knowledge, not just the task</strong> (#135, #311, #357, #387, #389). An OKF knowledge bundle, a SemVer guide enforced in CLAUDE.md and pinned against drift, a history deck, a knowledge graph of the architecture. <em>Lean reasoning:</em> relearning is waste; standard work has to be readable by whoever does the work.</p><h3 id="era-3--the-cloud-project-26-and-27-september" tabindex="-1">Era 3 · The cloud project (26 and 27 September) <a class="header-anchor" href="#era-3--the-cloud-project-26-and-27-september" aria-label="Permalink to &quot;Era 3 · The cloud project (26 and 27 September)&quot;">​</a></h3><p><strong>25 · One place for all of it</strong> (26 September 09:23). I moved all ESI work into a Claude project wired to GitHub. <em>Lean reasoning:</em> visual management and a single source of truth. <em>Evidence:</em> every ask, decision and merge since then is timestamped in one place; this document is built on that.</p><p><strong>26 · Green before new work</strong> (26 September 09:39). Five red PRs had to go green before the 11.0 plan started. <em>Lean reasoning:</em> stop the line and fix it before starting anything new. <em>Evidence:</em> four merged by 15:11, three size-limit bumps combined into one; Phase 0 started on a green baseline.</p><p><strong>27 · Fix, don&#39;t drop</strong> (26 September 12:02). The recommendation on size-limit 13 was to stay on v12 and close the PR. I said &quot;Make the fix and I&#39;ll merge.&quot; <em>Lean reasoning:</em> a workaround leaves the problem in the system. <em>Evidence:</em> a one-fixture guard, green in nine minutes.</p><p><strong>28 · Keep the standard stable, and decide once</strong> (26 September 15:37). &quot;Go&quot; to all four plan decisions: target 11.0.0 (npm was already at 10.x), keep pino and zod as runtime dependencies, keep Jest, npm, release-please and Dependabot rather than switching tools mid-programme, and make Node 22 the floor because Node 20 left support in April 2026. <em>Lean reasoning:</em> changing tools mid-stream is mura and muri with no customer value. Decide the standard, then let the work flow against it. <em>Evidence:</em> Phase 1 started within a minute and closed that afternoon; nothing has reopened any of the four. <em>Honest note:</em> the four decisions waited 5 h 45 min for my answer, the longest wait in the programme. Ask for decisions like this early.</p><p><strong>29 · Docs last</strong> (26 September 15:37). The comprehensive rewrite of READMEs, guides and examples is the final phase. <em>Lean reasoning:</em> just-in-time. Documenting an API that three phases are about to change is inventory I would scrap.</p><p><strong>30 · Keep the beta routes</strong> (26 September 16:06). SKINR, Paragon Hub and military campaign routes stay supported although they postdate the spec snapshot. <em>Lean reasoning:</em> value is what ESI serves today. <em>Evidence:</em> once the compatibility date moved, the spec carried all 14 routes and a planned PR was dropped. Keeping them removed work.</p><p><strong>31 · Make the backlog pull</strong> (26 September 16:09). Triage the 46 open issues into 11.0, safely. <em>Lean reasoning:</em> an untriaged backlog is invisible inventory; release and phase labels turn it into a pull system. <em>Evidence:</em> 46 issues in 58 minutes; 35 in 11.0, each with one phase label; 8 closed with evidence after I approved.</p><p><strong>32 · Go and see, every night</strong> (26 September 19:45). Every public example runs nightly against live ESI and opens an issue on failure. <em>Lean reasoning:</em> genchi genbutsu, and an andon cord that pulls itself. <em>Evidence:</em> the first live run passed 22 of 26. The four failures were real library bugs (three 404s from a stale compatibility date, a skyhooks schema that could never succeed), which drove the next decision.</p><p><strong>33 · Take the breaking fixes; match the wire</strong> (27 September 03:48 and 06:53). Raise the default compatibility date to 2026-08-18, correct the skyhooks schema, return <code>getChangelog</code> as ESI sends it. <em>Lean reasoning:</em> same as decision 19, and doing it inside 11.0 puts the migration cost into one major. <em>Evidence:</em> #423, #424, #428 merged; every public example then passed against live ESI.</p><p><strong>34 · Stop producing what nobody pulls</strong> (27 September 06:54). One Dependabot PR per ecosystem, no patch bumps, and release-please opens a release only after a feature, a breaking change or an explicit <code>Release-As</code>. <em>Lean reasoning:</em> this closes the two overproduction streams from Eras 1 and 2 at their source. Three earlier attempts at grouping Dependabot (#72, #207, #318) had treated the symptom; this one changed the policy. <em>Evidence:</em> #425 opened three minutes after I asked; eight bot PRs retired; no per-dependency PRs since. <em>For Claude:</em> never propose a patch release or a single-dependency PR. An urgent fix uses <code>force-release</code>.</p><p><strong>35 · Keep the standard current, and give me feedback on requirements</strong> (27 September 06:57). Charter revision 2 and a standalone EARS check. <em>Lean reasoning:</em> a stale standard is worse than none because people follow it. <em>Evidence:</em> #429 and #427 merged within two hours; the first EARS run verified all 402 requirements in about 40 seconds; re-checking the charter against the code found a real security gap, a <code>..</code> path parameter that redirected a request (#430).</p><p><strong>36 · Fix it now</strong> (27 September 09:07). File and fix the public contracts failure the nightly surfaced. <em>Lean reasoning:</em> a known defect left in place grows interest. <em>Evidence:</em> cause found in two minutes, fixed the same day (#433, #434).</p><p><strong>37 · Never lower the gate; add capacity</strong> (27 September 11:41). When the PR mutation step could not finish on the request handler, I chose to raise its time budget rather than merge with it red. <em>Lean reasoning:</em> loosening a gate trades a visible wait for invisible defects. <em>Evidence:</em> 20 then 30 minutes (#440, #434), and the thread also split its tests so existing mutant results were reused, which is the better fix: less work, not more time. <em>For Claude:</em> no floor is ever lowered. If a gate cannot finish, make the work smaller or give the gate capacity, in that order.</p><p><strong>38 · Please merge as needed</strong> (27 September 11:42). Merge authority moved from me to the threads. <em>Lean reasoning:</em> decide where the information is. A thread knows better than anyone whether its PR is green, mergeable and fully reviewed; my confirming that by hand added a wait and no information. Because I was available intermittently, I batched, and the batches caused integration defects. <em>Evidence:</em> ready-to-merged went from 42 minutes to zero; lead time for clean changes from about two hours to 17 minutes; no conflict, red <code>master</code> or lost change since. <em>For Claude:</em> when a PR meets the gate, merge it. Bring me forks, breaking changes, naming, and anything that cannot be undone.</p><p><strong>39 · Fix the detector, not the alarm</strong> (27 September 11:45). &quot;Figure out a better way&quot; for the recurring payload-drift PRs. <em>Lean reasoning:</em> five whys. Processing false alarms faster is still waste. <em>Evidence:</em> the bot flagged optional fields as drift; #441 stopped that and made it close a drift PR only after a clean run contradicts it. 18 minutes from ask to <code>master</code>.</p><p><strong>40 · No bridge between the core and the SDE</strong> (27 September). The static data export stays isolated from the ESI core, enforced by a lint in both directions (#462). <em>Lean reasoning:</em> coupling two products creates a changeover cost on every release of either. Anything that joins them belongs in a separate package above both.</p><p><strong>41 · Stop and reflect</strong> (27 September 16:24). Status, a docs refresh, and this record. <em>Lean reasoning:</em> hansei. Kaizen needs a measured current state to improve against.</p><hr><h2 id="part-5--where-the-evidence-says-i-was-wrong-or-late" tabindex="-1">Part 5 · Where the evidence says I was wrong, or late <a class="header-anchor" href="#part-5--where-the-evidence-says-i-was-wrong-or-late" aria-label="Permalink to &quot;Part 5 · Where the evidence says I was wrong, or late&quot;">​</a></h2><p>A record that only justifies is not credible. These are the places the data pushes back.</p><ul><li><strong>I kept the merge too long.</strong> For the first 26 hours of Era 3, and through the ramp-up of Era 2, merging by hand was the constraint. It cost half of all lead time in Era 3 and caused three integration defects in one day. It was reasonable caution while the operation was new. The data says it could have gone sooner.</li><li><strong>Four majors in ten weeks.</strong> Each major is a migration for every consumer. 11.0.0 is the correction: one major, held until a 13-row release gate is true, with every breaking change batched into it. That is a deliberate batch, and I accept it as inventory in exchange for one migration instead of several.</li><li><strong>Bursts.</strong> 262 commits in two days in September, four threads started within three minutes on 27 September. Both are mura. The second drew down the shared usage budget and caused four stalls totalling 382 agent-minutes.</li><li><strong>The release blockers.</strong> Publishing to npm still needs a manual dispatch (#378, #383), and it needs my GitHub App token. It costs nothing while 11.0 is held. It will be the constraint on release day.</li><li><strong>Tests did not run at the workstation in the cloud.</strong> I built <code>check:local</code> in Era 2 so the line would stop at the station. In Era 3 the agents&#39; environment could not install npm packages, so CI was the first test run and only 56% of CI runs passed first time. That is the next thing to fix.</li><li><strong>Two boards.</strong> Beads and GitHub drifted apart. One source of truth for work, not two.</li></ul><hr><h2 id="part-6--how-i-want-claude-to-work-with-me" tabindex="-1">Part 6 · How I want Claude to work with me <a class="header-anchor" href="#part-6--how-i-want-claude-to-work-with-me" aria-label="Permalink to &quot;Part 6 · How I want Claude to work with me&quot;">​</a></h2><p>These are the rules the record supports. When something is not covered here, apply the lens in Part 1.</p><ol><li><strong>The wire is the truth.</strong> If ESI sends it, the client must accept it; if ESI never sends it, the type must not promise it. Additions are tolerated, removals are breaking.</li><li><strong>Write the requirement first.</strong> An EARS rule and a failing scenario come before the code.</li><li><strong>One concern per pull request.</strong> Small batches are what make merge at green safe.</li><li><strong>The gate is the gate.</strong> Never lower a floor, add to a baseline, skip a test, or make a check non-blocking to get green. If the gate is wrong, fix the gate in its own PR.</li><li><strong>Merge at green.</strong> When a PR meets the gate and every review thread is answered and resolved, merge it. Don&#39;t wait for me.</li><li><strong>Bring me only the forks.</strong> Breaking changes, public naming, anything that cannot be undone, and releases. Otherwise pick the sensible default, say which, and keep going.</li><li><strong>Ask early, with a recommendation.</strong> A decision I can answer with one tap is a decision that does not wait five hours.</li><li><strong>Route failures to their owner.</strong> A failure your change did not cause is not a reason to block your change; file it, fix it separately, or port the fix, and say so.</li><li><strong>Don&#39;t produce what nobody pulled.</strong> No patch releases, no single-dependency bumps, no speculative features. If a planned item turns out unnecessary, drop it and say why.</li><li><strong>Fix the cause, not the symptom.</strong> If the same problem comes back, ask why it keeps coming back.</li><li><strong>Keep the standard current in the same change.</strong> If your change makes the charter, the roadmap or a guide untrue, fix the document in the same PR.</li><li><strong>Level the load.</strong> Start the most valuable work first and pace the rest, rather than starting everything at once.</li><li><strong>Every exception expires.</strong> Anything accepted as a known risk carries a reason and a date.</li><li><strong>Write down what you learned.</strong> If the next session would have to rediscover it, it goes in memory or in the repository.</li></ol><hr><h2 id="appendix-a--data-and-method" tabindex="-1">Appendix A · Data and method <a class="header-anchor" href="#appendix-a--data-and-method" aria-label="Permalink to &quot;Appendix A · Data and method&quot;">​</a></h2><ul><li><code>lean/data/all-prs.csv</code>: all 300 pull requests from #50 onwards (June to 27 September 2026) with author, branch, and created, merged and closed times, from the GitHub API.</li><li><code>lean/data/pr-flow.csv</code>: the 30 Era 3 and 4 pull requests with the time of my ask, PR open, ready and merged, and the derived intervals.</li><li><code>lean/data/event-log.csv</code>: every ask, decision card, usage-limit stall and merge batch in Era 3 and 4.</li><li>Era 1 and 2 lead times run from PR open to merge, because the build time before a local PR opened was never recorded. Era 3 and 4 lead times run from my ask, because the project records it. The two are not directly comparable; the table in Part 2 uses PR open to merge for every era so they are.</li><li>Flow efficiency in Era 3 takes about 21 minutes of work per change: roughly 1 to spin up, 8 to build, 7 for one clean CI run, 5 for review fixes. It counts a clean CI run as work, which a purist would not; counting only building, it was nearer 7%.</li><li>CI first-pass yield comes from the 100 most recent <code>ci.yml</code> runs (26 September 19:44 to 27 September 16:25).</li></ul><h2 id="appendix-b--the-lean-terms-as-i-use-them-in-software" tabindex="-1">Appendix B · The Lean terms as I use them in software <a class="header-anchor" href="#appendix-b--the-lean-terms-as-i-use-them-in-software" aria-label="Permalink to &quot;Appendix B · The Lean terms as I use them in software&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>In ESI.ts</th></tr></thead><tbody><tr><td>Value</td><td>What a consumer receives from ESI through the client, correct and verifiable</td></tr><tr><td>Value stream</td><td>Ask → specify → build → CI → review → merge → release → npm</td></tr><tr><td>Jidoka</td><td>The required checks behind <code>ci-success</code>; a line that stops itself</td></tr><tr><td>Andon</td><td>A failing check, a nightly that files an issue, a decision card</td></tr><tr><td>Poka-yoke</td><td>Generated-code checks, layer lint, shrink-only baselines, the EARS audit</td></tr><tr><td>Standard work</td><td>The charter, CLAUDE.md, AGENTS.md, SEMVER.md, project memory</td></tr><tr><td>Kaizen</td><td>A process fix shipped as a PR, and never reversed (a ratchet)</td></tr><tr><td>Inventory</td><td>Green PRs waiting to merge, unreleased changes, unpulled bot PRs</td></tr><tr><td>Overproduction</td><td>Patch releases and bump PRs nobody asked for</td></tr><tr><td>Mura</td><td>Bursts of work followed by quiet</td></tr><tr><td>Muri</td><td>One person holding every approval</td></tr><tr><td>Genchi genbutsu</td><td>Nightly runs against live ESI</td></tr><tr><td>Hansei</td><td>Stopping to measure, as this document does</td></tr></tbody></table>',99)])])}const w=t(h,[["render",l]]);export{b as __pageData,w as default};
